    }
});

function set_print_format(frm) {
    let print_format = "";

    if (frm.doc.material_request_type === "Material Issue") {
        print_format = "Issuance to Production";
    } else {
        print_format = "PR_Form_Jinja";
    }

    frm.meta.default_print_format = print_format;

}

