  }
});

// Also handle visibility in child row edit (dialog view)
frappe.ui.form.on('Asset Movement Item', {
  form_render: function(frm, cdt, cdn) {
    let show_field = frm.doc.purpose === 'Receipt';
    let df = frappe.meta.get_docfield(cdt, 'custom_to_section', frm.doc.name);
    if (df) df.hidden = !show_field;

    // Also manually hide the input element (in case Frappe doesn't apply df.hidden immediately)
    const row = locals[cdt][cdn];
    const field = frappe.container.page.fields_dict;
    const wrapper = cur_frm.fields_dict.items.grid.grid_rows_by_docname[cdn].fields_dict.custom_to_section?.df;
    if (wrapper) {
      wrapper.hidden = !show_field;
    }
  }
});

frappe.ui.form.on('Asset Movement Item', {
  form_render: function(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
