function format_payroll_date(date_obj) {
    return (date_obj.getMonth() + 1) + '/' + date_obj.getDate() + '/' + date_obj.getFullYear();
}

function format_iso_date(date_obj) {
    const month = String(date_obj.getMonth() + 1).padStart(2, '0');
    const day = String(date_obj.getDate()).padStart(2, '0');
    return date_obj.getFullYear() + '-' + month + '-' + day;
}

function payroll_label_to_date(label) {
    if (!label) return null;
    const value = String(label).trim();

    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
        const parts = value.split('-').map(part => cint(part));
        return new Date(parts[0], parts[1] - 1, parts[2]);
    }

    const parts = value.split('/').map(part => cint(part));
    if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) return null;
    return new Date(parts[2], parts[0] - 1, parts[1]);
}

function payroll_label_to_iso(label) {
    const date_obj = payroll_label_to_date(label);
    return date_obj ? format_iso_date(date_obj) : '';
}

function get_current_payroll_period_label() {
    const today = frappe.datetime.str_to_obj(frappe.datetime.get_today());
    const year = today.getFullYear();
    const month = today.getMonth();
    const day = today.getDate();

    if (typeof cur_frm !== 'undefined' && cur_frm && cur_frm.__employee_attendance_payroll_type === 'Weekly') {
        const sunday = new Date(today);
        sunday.setDate(today.getDate() + ((7 - today.getDay()) % 7));
        return format_payroll_date(sunday);
    }

    if (day <= 15) {
        return format_payroll_date(new Date(year, month, 15));
    }
    return format_payroll_date(new Date(year, month, Math.min(30, new Date(year, month + 1, 0).getDate())));
}

function add_weekly_payroll_period_options(options, base) {
    const first = new Date(base.getFullYear(), base.getMonth(), 1);
    const last = new Date(base.getFullYear(), base.getMonth() + 1, 0);
    const sunday = new Date(first);
    sunday.setDate(first.getDate() + ((7 - first.getDay()) % 7));

    while (sunday <= last) {
        options.push(format_payroll_date(new Date(sunday)));
        sunday.setDate(sunday.getDate() + 7);
    }
}

function setup_payroll_period_options(frm) {
    const today = frappe.datetime.str_to_obj(frappe.datetime.get_today());
    const options = [];
    const payroll_type = frm.__employee_attendance_payroll_type || '';

    for (let offset = -6; offset <= 6; offset++) {
        const base = new Date(today.getFullYear(), today.getMonth() + offset, 1);
        if (payroll_type !== 'Weekly') {
            options.push(format_payroll_date(new Date(base.getFullYear(), base.getMonth(), 15)));
            options.push(format_payroll_date(new Date(base.getFullYear(), base.getMonth(), Math.min(30, new Date(base.getFullYear(), base.getMonth() + 1, 0).getDate()))));
        }
        if (payroll_type !== 'Monthly') {
            add_weekly_payroll_period_options(options, base);
        }
    }

    frm.set_df_property('payroll_period', 'options', Array.from(new Set(options)).join(String.fromCharCode(10)));
}

function ensure_user_payroll_type(frm) {
    if (frm.__employee_attendance_payroll_type_loaded || frm.__loading_employee_attendance_payroll_type) return;

    frm.__loading_employee_attendance_payroll_type = true;
    frappe.call({
        method: 'qcmc_logic.api.employee_attendance_schedule.get_current_user_payroll_type',
        callback(r) {
            frm.__employee_attendance_payroll_type = (r.message || '').trim();
            frm.__employee_attendance_payroll_type_loaded = true;
            frm.__loading_employee_attendance_payroll_type = false;
            setup_payroll_period_options(frm);
        },
        error() {
            frm.__loading_employee_attendance_payroll_type = false;
        }
    });
}

function get_payroll_period_input_value(frm) {
    const field = frm.fields_dict.payroll_period;
    if (!field) return frm.doc.payroll_period || '';

    const input_value = field.$input ? (field.$input.val() || '') : '';
    return input_value || field.value || frm.doc.payroll_period || '';
}

function setup_payroll_period_change_handler(frm) {
    const field = frm.fields_dict.payroll_period;
    if (!field || !field.$input) return;

    field.$input.off('change.eas_payroll_period input.eas_payroll_period');
    field.$input.on('change.eas_payroll_period input.eas_payroll_period', function() {
        handle_payroll_period_change(frm, get_payroll_period_input_value(frm));
    });
}

function sync_payroll_period_from_input(frm) {
    [100, 400, 900].forEach(function(delay) {
        setTimeout(function() {
            const value = get_payroll_period_input_value(frm);
            if (value && value !== frm.doc.payroll_period) {
                handle_payroll_period_change(frm, value);
            } else if (value) {
                set_payroll_period_dates(frm, value).then(function() {
                    mark_viewer_clean(frm);
                });
            }
        }, delay);
    });
}

async function handle_payroll_period_change(frm, value) {
    if (frm.__handling_payroll_period_change) return;
    frm.__handling_payroll_period_change = true;

    try {
        if (value && frm.doc.payroll_period !== value) {
            frm.doc.payroll_period = value;
        }

        await set_payroll_period_dates(frm, value);
        clear_generated_data(frm);
        apply_payroll_period_visibility(frm);
        render_employee_picker(frm);
        render_attendance_viewer(frm, []);
        ensure_employee_directory(frm, function() {
            apply_payroll_period_visibility(frm);
            render_employee_picker(frm);
            mark_viewer_clean(frm);
        });
    } finally {
        frm.__handling_payroll_period_change = false;
    }
}

function mark_viewer_clean(frm) {
    frm.doc.__unsaved = 0;
    frm.dirty = false;
    frm.disable_save();
    frm.refresh_header();
}

function apply_payroll_period_visibility(frm) {
    const show = !!frm.doc.payroll_period;
    [
        'employees_section',
        'employee_list_html',
        'selected_employee_name',
        'attendance_section',
        'attendance_viewer'
    ].forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (!field) return;

        frm.set_df_property(fieldname, 'hidden', show ? 0 : 1);
        frm.toggle_display(fieldname, show);
        if (field.wrapper) {
            $(field.wrapper).toggle(show);
        }
    });
    const status_field = frm.fields_dict.selected_employee_status;
    if (status_field) {
        frm.set_df_property('selected_employee_status', 'hidden', 1);
        frm.toggle_display('selected_employee_status', false);
        if (status_field.wrapper) {
            $(status_field.wrapper).hide();
        }
    }
    frm.refresh_fields();
}

function apply_viewer_titles(frm) {
    const sourceTitle = 'Employee Attendance Schedule';
    const viewerTitle = __('Employee Attendance Viewer');
    try {
        if (frm.page && frm.page.set_title) {
            frm.page.set_title(viewerTitle);
        }
    } catch (e) {}

    setTimeout(function() {
        const selectors = [
            '.breadcrumb .breadcrumb-item.active',
            '.page-breadcrumbs .breadcrumb-item.active',
            '.page-head .title-text'
        ];
        selectors.forEach(function(selector) {
            $(selector).each(function() {
                const text = ($(this).text() || '').trim();
                if (text === sourceTitle) {
                    $(this).text(viewerTitle);
                }
            });
        });

        $('.breadcrumb a, .page-breadcrumbs a').each(function() {
            const text = ($(this).text() || '').trim();
            if (text !== sourceTitle && text !== viewerTitle) return;

            const $span = $('<span class="eas-viewer-breadcrumb-text"></span>').text(viewerTitle);
            $(this).replaceWith($span);
        });
    }, 0);
}

