async function set_payroll_period_dates(frm, payroll_period) {
    const period = payroll_period || frm.doc.payroll_period;
    if (!period) return;

    const pay_day = payroll_label_to_date(period);
    if (!pay_day) return;

    let from_date;
    let to_date;
    if (pay_day.getDay() === 0 && pay_day.getDate() !== 15 && pay_day.getDate() !== 30) {
        from_date = new Date(pay_day.getFullYear(), pay_day.getMonth(), pay_day.getDate() - 6);
        to_date = pay_day;
    } else if (pay_day.getDate() === 15) {
        from_date = new Date(pay_day.getFullYear(), pay_day.getMonth() - 1, 23);
        to_date = new Date(pay_day.getFullYear(), pay_day.getMonth(), 7);
    } else {
        from_date = new Date(pay_day.getFullYear(), pay_day.getMonth(), 8);
        to_date = new Date(pay_day.getFullYear(), pay_day.getMonth(), 22);
    }

    const values = {
        from_date: format_iso_date(from_date),
        to_date: format_iso_date(to_date),
        pay_day: format_iso_date(pay_day)
    };

    frm.doc.from_date = values.from_date;
    frm.doc.to_date = values.to_date;
    frm.doc.pay_day = values.pay_day;

    await frm.set_value('from_date', values.from_date);
    await frm.set_value('to_date', values.to_date);
    await frm.set_value('pay_day', values.pay_day);

    ['from_date', 'to_date', 'pay_day'].forEach(function(fieldname) {
        frm.refresh_field(fieldname);
    });
}

function clear_generated_data(frm) {
    apply_payroll_period_visibility(frm);
    frm.set_value('employee_list_data', '');
    frm.set_value('selected_employee', '');
    frm.set_value('selected_employee_name', '');
    frm.set_value('selected_employee_status', '');
    frm.set_value('generated_on', '');
    frm.set_value('total_employees', 0);
    frm.set_value('scheduled_employees', 0);
    frm.set_value('generated_rows', 0);
    frm.set_value('skipped_employees_count', 0);
    frm.set_value('skipped_employees', '');
    render_shift_setup_action(frm, '');
    render_attendance_viewer(frm, []);
    render_employee_picker(frm);
    hide_viewer_chrome(frm);
    mark_viewer_clean(frm);
}

function parse_employee_list(frm) {
    if (!frm.doc.employee_list_data) return [];
    try {
        return JSON.parse(frm.doc.employee_list_data) || [];
    } catch (e) {
        console.warn('Unable to parse employee list data', e);
        return [];
    }
}

function get_employee_directory_cache_key(frm) {
    return [
        frappe.session.user || '',
        frm.doc.company || '',
        frm.doc.payroll_period || ''
    ].join('|');
}

function has_current_employee_directory(frm) {
    return frm.__employee_directory_cache_key === get_employee_directory_cache_key(frm);
}

function ensure_employee_directory(frm, callback) {
    if (!frm.doc.payroll_period) {
        if (callback) callback([]);
        return;
    }

    const cache_key = get_employee_directory_cache_key(frm);
    const existing = has_current_employee_directory(frm) ? parse_employee_list(frm) : [];
    if (existing.length || has_current_employee_directory(frm)) {
        if (callback) callback(existing);
        return;
    }

    if (frm.__loading_employee_directory) {
        frm.__employee_directory_callbacks = frm.__employee_directory_callbacks || [];
        if (callback) frm.__employee_directory_callbacks.push(callback);
        return;
    }

    frm.__loading_employee_directory = true;
    frm.__employee_directory_callbacks = frm.__employee_directory_callbacks || [];
    if (callback) frm.__employee_directory_callbacks.push(callback);

    frappe.call({
        method: 'qcmc_logic.api.employee_attendance_schedule.get_employee_directory',
        args: {
            payroll_period: payroll_label_to_iso(frm.doc.payroll_period),
            company: frm.doc.company
        },
        callback(r) {
            const result = r.message || {};
            const employees = result.employees || [];
            frm.__loading_employee_directory = false;
            frm.set_value('from_date', result.from_date || frm.doc.from_date);
            frm.set_value('to_date', result.to_date || frm.doc.to_date);
            frm.set_value('pay_day', result.pay_day || frm.doc.pay_day);
            frm.set_value('total_employees', result.total_employees || 0);
            frm.set_value('scheduled_employees', result.scheduled_employees || 0);
            frm.set_value('skipped_employees_count', (result.skipped_employees || []).length);
            frm.set_value('skipped_employees', (result.skipped_employees || []).map(emp => emp.employee + ' - ' + emp.employee_name).join(String.fromCharCode(10)));
            frm.set_value('employee_list_data', JSON.stringify(employees));
            frm.__employee_directory_cache_key = cache_key;
            clear_exception_dashboard_cache(frm);
            render_employee_picker(frm);
            ensure_exception_dashboard(frm, function() {
                render_employee_picker(frm);
            });
            mark_viewer_clean(frm);
            (frm.__employee_directory_callbacks || []).forEach(function(fn) { fn(employees); });
            frm.__employee_directory_callbacks = [];
        },
        error() {
            frm.__loading_employee_directory = false;
            (frm.__employee_directory_callbacks || []).forEach(function(fn) { fn([]); });
            frm.__employee_directory_callbacks = [];
        }
    });
}

function clear_exception_dashboard_cache(frm) {
    frm.__exception_dashboard = null;
    frm.__loading_exception_dashboard = false;
    frm.__employee_exception_filter = '';
}

function ensure_exception_dashboard(frm, callback) {
    if (!frm.doc.payroll_period) {
        if (callback) callback(null);
        return;
    }
    if (frm.__exception_dashboard) {
        if (callback) callback(frm.__exception_dashboard);
        return;
    }
    if (frm.__loading_exception_dashboard) return;

    frm.__loading_exception_dashboard = true;
    frappe.call({
        method: 'qcmc_logic.api.employee_attendance_schedule.get_exception_dashboard',
        args: {
            payroll_period: payroll_label_to_iso(frm.doc.payroll_period),
            company: frm.doc.company
        },
        callback(r) {
            frm.__loading_exception_dashboard = false;
            frm.__exception_dashboard = r.message || {};
            if (callback) callback(frm.__exception_dashboard);
        },
        error() {
            frm.__loading_exception_dashboard = false;
            if (callback) callback(null);
        }
    });
}

function get_exception_dashboard_config() {
    return [
        ['late', __('Late Employees')],
        ['absent', __('Absent Employees')],
        ['no_shift_setup', __('No Shift Setup')],
        ['missing_time_out', __('Missing Time Out')],
        ['with_ot', __('With OT')]
    ];
}

function get_exception_employee_set(frm, key) {
    const rows = (((frm.__exception_dashboard || {}).employees || {})[key]) || [];
    const set = {};
    rows.forEach(function(row) {
        if (row.employee) set[row.employee] = true;
    });
    return set;
}

function get_filtered_employees(frm, employees) {
    const key = frm.__employee_exception_filter;
    if (!key) return employees;

    const employeeSet = get_exception_employee_set(frm, key);
    return employees.filter(function(employee) {
        return !!employeeSet[employee.employee];
    });
}

function render_exception_dashboard_html(frm) {
    const dashboard = frm.__exception_dashboard || {};
    const counts = dashboard.counts || {};
    const loading = frm.__loading_exception_dashboard && !frm.__exception_dashboard;
    const active = frm.__employee_exception_filter || '';

    const cards = get_exception_dashboard_config().map(function(item) {
        const key = item[0];
        const label = item[1];
        const count = loading ? '...' : cint(counts[key] || 0);
        return '<button class="eas-exception-card ' + (active === key ? 'is-active' : '') + '" type="button" data-exception="' + key + '">' +
            '<span>' + frappe.utils.escape_html(label) + '</span>' +
            '<strong>' + count + '</strong>' +
        '</button>';
    }).join('');

    return '<div class="eas-exception-dashboard">' +
        cards +
        (active ? '<button class="btn btn-xs btn-default eas-exception-clear" type="button">' + __('Clear') + '</button>' : '') +
    '</div>';
}

function render_employee_picker(frm) {
    if (!frm.fields_dict.employee_list_html) return;
    if (frm.wrapper) {
        $(frm.wrapper).addClass('eas-viewer-compact');
    }
    render_period_details_toggle(frm);
    apply_payroll_period_visibility(frm);
    if (!frm.doc.payroll_period) {
        frm.fields_dict.employee_list_html.$wrapper.empty();
        return;
    }

    let employees = has_current_employee_directory(frm) ? parse_employee_list(frm) : [];
    const wrapper = frm.fields_dict.employee_list_html.$wrapper;
    wrapper.off('click.eas_employee_table');

    ensure_employee_table_style();
    if (frm.doc.selected_employee && !frm.__show_employee_picker) {
        render_selected_employee_card(frm, wrapper);
    } else {
        render_employee_table(frm, wrapper, employees, '');
    }

    if (!employees.length && (!frm.doc.selected_employee || frm.__show_employee_picker)) {
        ensure_employee_directory(frm, function(loadedEmployees) {
            employees = loadedEmployees || parse_employee_list(frm);
            render_employee_table(frm, wrapper, employees, '');
        });
    }

    wrapper.on('click.eas_employee_table', '.eas-employee-change', function() {
        frm.__show_employee_picker = true;
        render_employee_table(frm, wrapper, employees.length ? employees : (has_current_employee_directory(frm) ? parse_employee_list(frm) : []), '');
        ensure_employee_directory(frm, function(loadedEmployees) {
            employees = loadedEmployees || [];
            render_employee_table(frm, wrapper, employees, '');
        });
    });

    wrapper.on('click.eas_employee_table', '.eas-employee-table-row', function() {
        const employee = $(this).attr('data-employee') || '';
        const employee_name = $(this).attr('data-employee-name') || '';
        frm.__employee_table_scroll_top = wrapper.find('.eas-employee-table-wrap').scrollTop() || 0;
        frm.__show_employee_picker = false;
        if (!employee) return;

        wrapper.find('.eas-employee-table-row').removeClass('is-selected');
        $(this).addClass('is-selected');
        load_employee_schedule(frm, employee, employee_name);
    });
}

