    wrapper.html(
        '<div class="eas-employee-selected-card">' +
            '<div class="eas-employee-selected-text">' + frappe.utils.escape_html(label) + '</div>' +
            '<button class="btn btn-xs btn-default eas-employee-change" type="button">Change</button>' +
        '</div>'
    );
}

function render_employee_table(frm, wrapper, employees, keyword) {
    const text = (keyword || '').toLowerCase().trim();
    const selected_employee = frm.doc.selected_employee || '';
    const source = employees || [];
    const rows = source.filter(function(employee) {
        if (!text) return true;
        const haystack = [employee.employee, employee.employee_name, employee.department, employee.default_shift, employee.status]
            .filter(Boolean).join(' ').toLowerCase();
        return haystack.indexOf(text) !== -1;
    });

    const body = rows.map(function(employee) {
        const status = employee.status || '';
        const status_class = status === 'No Shift Setup' ? ' no-shift' : '';
        const selected_class = employee.employee === selected_employee ? ' is-selected' : '';

        return '<tr class="eas-employee-table-row' + selected_class + '" data-employee="' + frappe.utils.escape_html(employee.employee || '') + '" data-employee-name="' + frappe.utils.escape_html(employee.employee_name || '') + '">' +
            '<td class="eas-employee-id">' + frappe.utils.escape_html(employee.employee || '') + '</td>' +
            '<td>' + frappe.utils.escape_html(employee.employee_name || '') + '</td>' +
        '</tr>';
    }).join('');

    const empty_html = '<div class="eas-employee-table-empty">' + (text ? 'No employee found.' : 'Loading employees...') + '</div>';

    wrapper.html(
        '<div class="eas-employee-table-picker">' +
            '<div class="eas-employee-table-wrap">' +
                (rows.length ? '<table class="eas-employee-table">' +
                    '<thead><tr>' +
                        '<th style="width:140px;">Employee ID</th>' +
                        '<th>Employee Name</th>' +
                    '</tr></thead>' +
                    '<tbody>' + body + '</tbody>' +
                '</table>' : empty_html) +
            '</div>' +
        '</div>'
    );

    const scroll_top = frm.__employee_table_scroll_top || 0;
    if (scroll_top) {
        wrapper.find('.eas-employee-table-wrap').scrollTop(scroll_top);
    }
}

