        ['authorization_no', 'OT Slip'],
        ['rest_day', 'RestDay'],
        ['holiday_type', 'HolidayType'],
        ['leave_type', 'LeaveType'],
        ['department', 'Department'],
        ['shift', 'Shift']
    ];

    if (!rows || !rows.length) {
        field.$wrapper.html('<div class="eas-attendance-viewer"><div class="eas-attendance-empty">Select an employee to view the attendance schedule.</div></div>');
