function get_overtime_type_summary(rows) {
    const totals = {};
    (rows || []).forEach(function(row) {
        const hours = flt(row.valid_ot);
        if (!hours) return;
        const type = (row.overtime_type || 'No OT Type').trim();
        totals[type] = (totals[type] || 0) + hours;
    });

    const chips = Object.keys(totals).sort().map(function(type) {
        return '<span class="eas-attendance-total eas-attendance-ot-type">' +
            frappe.utils.escape_html(type) +
            ' <strong>' + format_attendance_total(totals[type]) + '</strong>' +
        '</span>';
    }).join('');

    if (!chips) return '';
    return '<span class="eas-attendance-breakdown-label">OT Breakdown</span>' + chips;
}

function format_attendance_total(value) {
    const total_minutes = Math.round(flt(value) * 60);
    const hours = Math.floor(total_minutes / 60);
    const minutes = total_minutes % 60;

    if (hours && minutes) return hours + 'h ' + minutes + 'm';
    if (hours) return hours + 'h';
    return minutes + 'm';
}

function get_attendance_row_class(row) {
    const is_holiday = !!row.holiday_type || !!row.rest_day;
    const is_absent = row.attendance_status === 'Absent' || (!!row.sched_time_start && !row.time_in && !row.leave_type && !is_holiday);
    const is_late = flt(row.late_hours) > 0;

    if (is_holiday) return 'eas-row-holiday';
    if (row.leave_type) return 'eas-row-leave';
    if (is_absent) return 'eas-row-absent';
    if (is_late) return 'eas-row-late';
    return '';
}

function format_attendance_cell(row, fieldname) {
    const value = row[fieldname] == null ? '' : String(row[fieldname]);
    const label = frappe.utils.escape_html(value);
    if (!value) return '';

    if (fieldname === 'leave_type') {
        if (!row.leave_application) return label;
        const href = '/app/' + frappe.router.slug('Leave Application') + '/' + encodeURIComponent(row.leave_application);
        return '<a class="eas-attendance-link" href="' + href + '">' + label + '</a>';
    }

    const link_doctypes = {
        authorization_no: 'Overtime Slip'
    };
    const doctype = link_doctypes[fieldname];
    if (!doctype) return label;

    const href = '/app/' + frappe.router.slug(doctype) + '/' + encodeURIComponent(value);
    return '<a class="eas-attendance-link" href="' + href + '">' + label + '</a>';
}

function update_selected_employee(frm, employee, employee_name, status) {
    frm.set_value('selected_employee', employee || '');
    frm.set_value('selected_employee_name', employee ? [employee, employee_name].filter(Boolean).join(' - ') : '');
    frm.set_value('selected_employee_status', status || '');
    render_shift_setup_action(frm, status || '');
}

function render_shift_setup_action(frm, status) {
    const field = frm.fields_dict.selected_employee_status;
    if (field && field.$wrapper) {
        field.$wrapper.find('.eas-shift-setup-actions').remove();
    }

    clear_shift_setup_toolbar_actions(frm);
    if (status !== 'No Shift Setup' || !frm.doc.selected_employee || !frm.page) return;

    add_shift_setup_action_item(frm, __('Open Roster'), function() {
        open_roster_for_selected_employee(frm);
    });
    add_shift_setup_action_item(frm, __('Create Shift Assignment'), function() {
        show_create_shift_assignment_dialog(frm);
    });
    add_shift_setup_action_item(frm, __('Copy Previous Period'), function() {
        copy_previous_period_schedule(frm);
    });

    if (frm.page.show_actions_menu) {
        frm.page.show_actions_menu();
    }
}

function add_shift_setup_action_item(frm, label, handler) {
    const item = frm.page.add_action_item(label, handler);
    item.addClass('eas-shift-setup-action-item');
}

function clear_shift_setup_toolbar_actions(frm) {
    if (!frm.page || !frm.page.actions) return;
    frm.page.actions.find('.eas-shift-setup-action-item').remove();
}

function get_schedule_period_args(frm) {
    return {
        payroll_period: payroll_label_to_iso(frm.doc.payroll_period),
        from_date: frm.doc.from_date || '',
        to_date: frm.doc.to_date || ''
    };
}

function reload_selected_employee_schedule(frm) {
    if (!frm.doc.selected_employee) return;
    load_employee_schedule(frm, frm.doc.selected_employee, '');
    ensure_employee_directory(frm, function() {
        render_employee_picker(frm);
    });
}

function open_roster_for_selected_employee(frm) {
    if (!frm.doc.selected_employee) {
        frappe.msgprint(__('Please select an employee first.'));
        return;
    }

    const params = new URLSearchParams({
        employee: frm.doc.selected_employee || '',
        company: frm.doc.company || '',
        date: frm.doc.from_date || ''
    });
    window.location.href = '/hr/roster?' + params.toString();
}

function show_create_shift_assignment_dialog(frm) {
    if (!frm.doc.selected_employee) {
        frappe.msgprint(__('Please select an employee first.'));
        return;
    }

    const dialog = new frappe.ui.Dialog({
        title: __('Create Shift Assignment'),
        fields: [
            {
                fieldtype: 'Link',
                fieldname: 'shift_type',
                label: __('Shift Type'),
                options: 'Shift Type',
                reqd: 1
            },
            {
                fieldtype: 'HTML',
                fieldname: 'period_note'
            }
        ],
        primary_action_label: __('Create'),
        primary_action(values) {
            if (!values.shift_type) return;
            const period = get_schedule_period_args(frm);
            frappe.call({
                method: 'qcmc_logic.api.employee_attendance_schedule.create_current_period_shift_assignment',
                args: {
                    employee: frm.doc.selected_employee,
                    shift_type: values.shift_type,
                    payroll_period: period.payroll_period,
                    from_date: period.from_date,
                    to_date: period.to_date
                },
                freeze: true,
                freeze_message: __('Creating shift assignment...'),
                callback(r) {
                    const result = r.message || {};
                    dialog.hide();
                    frappe.show_alert({
                        message: __('Created Shift Assignment {0}.', [result.name || '']),
                        indicator: 'green'
                    });
                    clear_employee_directory_cache(frm);
                    reload_selected_employee_schedule(frm);
                }
            });
        }
    });

    dialog.fields_dict.period_note.$wrapper.html(
        '<div class="text-muted">' + __('This creates an active assignment from {0} to {1}.', [frm.doc.from_date || '', frm.doc.to_date || '']) + '</div>'
    );
    dialog.show();
}

function copy_previous_period_schedule(frm) {
    if (!frm.doc.selected_employee) {
        frappe.msgprint(__('Please select an employee first.'));
        return;
    }

    frappe.confirm(
        __("Copy this employee\'s previous payroll-period Shift Assignments into {0} to {1}?", [frm.doc.from_date || '', frm.doc.to_date || '']),
        function() {
            const period = get_schedule_period_args(frm);
            frappe.call({
                method: 'qcmc_logic.api.employee_attendance_schedule.copy_previous_period_shift_schedule',
                args: {
                    employee: frm.doc.selected_employee,
                    payroll_period: period.payroll_period,
                    from_date: period.from_date,
                    to_date: period.to_date
                },
                freeze: true,
                freeze_message: __('Copying previous schedule...'),
                callback(r) {
                    const result = r.message || {};
                    frappe.show_alert({
                        message: __('Copied {0} Shift Assignment(s) from the previous period.', [result.count || 0]),
                        indicator: 'green'
                    });
                    clear_employee_directory_cache(frm);
                    reload_selected_employee_schedule(frm);
                }
            });
        }
    );
}

function clear_employee_directory_cache(frm) {
    frm.doc.employee_list_data = '';
    frm.refresh_field('employee_list_data');
    clear_exception_dashboard_cache(frm);
}

function load_employee_schedule(frm, employee, employee_name) {
    if (!employee) return;

    const employees = parse_employee_list(frm);
    const current = employees.find(function(row) { return row.employee === employee; }) || {};

    frappe.call({
        method: 'qcmc_logic.api.employee_attendance_schedule.get_employee_schedule',
        args: {
            employee: employee,
            payroll_period: payroll_label_to_iso(frm.doc.payroll_period),
            company: frm.doc.company
        },
        freeze: true,
        freeze_message: __('Loading attendance schedule...'),
        callback(r) {
            const result = r.message || {};
            update_selected_employee(frm, employee, result.employee_name || employee_name || current.employee_name, result.status || current.status);
            frm.set_value('generated_rows', (result.rows || []).length);
            frm.set_value('generated_on', frappe.datetime.now_datetime());
            render_attendance_viewer(frm, result.rows || []);
            render_employee_picker(frm);
            hide_viewer_chrome(frm);
            mark_viewer_clean(frm);

            if (!(result.rows || []).length && (result.status || current.status) === 'No Shift Setup') {
                frappe.show_alert({
                    message: __('{0} has no shift setup for this payroll period.', [result.employee_name || employee_name || employee]),
                    indicator: 'orange'
                });
            }
        }
    });
}

frappe.listview_settings["Employee Attendance Schedule"] = {
    onload(listview) {
        setup_attendance_schedule_viewer_list(listview);
    },

    refresh(listview) {
        setup_attendance_schedule_viewer_list(listview);
    }
};

function setup_attendance_schedule_viewer_list(listview) {
    apply_viewer_list_titles(listview);
    prevent_attendance_schedule_navigation();
    redirect_to_attendance_schedule_viewer();
}

function is_attendance_schedule_list_route() {
    const route = frappe.get_route ? frappe.get_route() : [];
    return route && route[0] === "List" && route[1] === "Employee Attendance Schedule";
}

function apply_viewer_list_titles(listview) {
    const sourceTitle = "Employee Attendance Schedule";
    const viewerTitle = __("Employee Attendance Viewer");

    if (listview && listview.page && listview.page.set_title) {
        listview.page.set_title(viewerTitle);
    }

    [0, 100, 300, 800].forEach((delay) => {
        setTimeout(() => neutralize_attendance_schedule_list_chrome(sourceTitle, viewerTitle), delay);
    });

    if (window.__eas_viewer_list_observer) {
        return;
    }

    window.__eas_viewer_list_observer = new MutationObserver(() => {
        if (is_attendance_schedule_list_route()) {
            neutralize_attendance_schedule_list_chrome(sourceTitle, viewerTitle);
        }
    });
    window.__eas_viewer_list_observer.observe(document.body, { childList: true, subtree: true });
}

function neutralize_attendance_schedule_list_chrome(sourceTitle, viewerTitle) {
    if (!is_attendance_schedule_list_route()) {
        return;
    }

    [
        ".breadcrumb .breadcrumb-item.active",
        ".page-breadcrumbs .breadcrumb-item.active",
        ".page-head .title-text"
    ].forEach((selector) => {
        $(selector).each(function() {
            const text = ($(this).text() || "").trim();
            if (text === sourceTitle) {
                $(this).text(viewerTitle);
            }
        });
    });

    $(".breadcrumb a, .page-breadcrumbs a").each(function() {
        const text = ($(this).text() || "").trim();
        if (text !== sourceTitle && text !== viewerTitle) return;

        $(this).replaceWith(
            $("<span class=\"eas-viewer-breadcrumb-text\"></span>").text(viewerTitle)
        );
    });

    $(".frappe-list a, .result a, .list-row-container a").each(function() {
        const href = $(this).attr("href") || "";
        const route = $(this).attr("data-route") || "";
        if (!href.includes("/app/employee-attendance-schedule/") && !route.includes("Employee Attendance Schedule")) {
            return;
        }

        $(this)
            .removeAttr("href")
            .removeAttr("data-route")
            .css({ cursor: "default", color: "inherit" });
    });
}

function prevent_attendance_schedule_navigation() {
    if (window.__eas_viewer_list_click_guard) {
        return;
    }

    window.__eas_viewer_list_click_guard = true;
    document.addEventListener("click", (event) => {
        if (!is_attendance_schedule_list_route()) {
            return;
        }

        const target = event.target;
        if ($(target).closest("input, button, select, textarea, .btn, .dropdown-menu, .filter-box, .list-paging-area, .list-row-checkbox, .checkbox, .avatar").length) {
            return;
        }

        const docLink = $(target).closest("a[href*='/app/employee-attendance-schedule/'], a[data-route*='Employee Attendance Schedule']");
        const docRow = $(target).closest(".list-row-container, .list-row, [data-name]");
        if (!docLink.length && !docRow.closest(".frappe-list, .result").length) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        neutralize_attendance_schedule_list_chrome(
            "Employee Attendance Schedule",
            __("Employee Attendance Viewer")
        );
    }, true);
}

function redirect_to_attendance_schedule_viewer() {
    if (!is_attendance_schedule_list_route() || window.__eas_viewer_redirecting) {
        return;
    }

    window.__eas_viewer_redirecting = true;

    frappe.db.get_list("Employee Attendance Schedule", {
        fields: ["name"],
        limit: 1,
        order_by: "creation asc"
    }).then((rows) => {
        if (rows && rows.length) {
            frappe.set_route("Form", "Employee Attendance Schedule", rows[0].name);
            return;
        }

        window.__eas_viewer_redirecting = false;
    }).catch(() => {
        window.__eas_viewer_redirecting = false;
    });

    setTimeout(() => {
        window.__eas_viewer_redirecting = false;
    }, 1500);
}

