                        fieldtype: 'Small Text',
                        label: __('Remarks')
                    },
                    {
                        fieldname: 'rfp_extra_operation',
                        fieldtype: 'Select',
                        label: __('Add / Minus'),
                        options: 'Add\nMinus',
                        default: 'Add'
                    },
                    {
                        fieldname: 'rfp_extra_value',
                        fieldtype: 'Currency',
                        label: __('Value'),
                        default: 0
                    }
                ],
                primary_action_label: __('Print'),
                primary_action: function(values) {
                    var params = {
                        doctype: frm.doc.doctype,
                        name: frm.doc.name,
                        format: 'PO RFP',
                        no_letterhead: 0,
                        rfp_extra_remarks: values.rfp_extra_remarks || '',
                        rfp_extra_operation: values.rfp_extra_operation || 'Add',
                        rfp_extra_value: Math.abs(flt(values.rfp_extra_value || 0))
                    };

                    var query = Object.keys(params)
                        .map(function(key) {
                            return encodeURIComponent(key) + '=' + encodeURIComponent(params[key]);
                        })
                        .join('&');
                    var print_url = frappe.urllib.get_full_url('/printview?' + query);

                    dialog.hide();
                    window.open(print_url, '_blank');
                }
            });

            dialog.show();
        });
    }
});

frappe.ui.form.on("Purchase Order", {
    onload: function(frm) {
        frm.trigger("set_naming_series");
    },

    company: function(frm) {
        frm.trigger("set_naming_series");
    },

    set_naming_series: function(frm) {
        if (!frm.doc.company) return;

        frappe.db.get_value("Company", frm.doc.company, "custom_doc_extension", function(r) {
            if (r && r.custom_doc_extension) {
                let ext = r.custom_doc_extension;

                // Define allowed series depending on extension
                let allowed_series = [];
                if (ext === "MCY" || ext === "QM") {
                    // Only basic series, no X
                    allowed_series = [`.${ext}.#`];
                } else if (ext === "Q" || ext === "M") {
                    // Allow both
                    allowed_series = [`.${ext}.#`, `.${ext}.X.#`];
                }

                // Set options dynamically
                frm.set_df_property("naming_series", "options", allowed_series.join("\n"));

                // Reset value only if current is not in allowed
                if (!allowed_series.includes(frm.doc.naming_series)) {
                    frm.set_value("naming_series", allowed_series[0]);
                }
            }
        });
    }
});

