let _dr_request_id = 0;
let _dr_debounce_timer = null;

frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        set_delivery_number(frm);

        $(document).off('click.dr_clear').on('click.dr_clear', 'li a, .dropdown-item', function() {
            if ($(this).text().trim() === __('Delivery Note') && cur_frm === frm) {
                _dr_request_id++; // invalidate in-flight fetches

                // Clear items table
                frm._clearing_items = true;
                frm.clear_table('items');
                frm.refresh_field('items');
                frm._clearing_items = false;

                // Clear delivery number
                frm.set_value('custom_delivery_number', '');
            }
        });

        // Hook refresh_field to re-evaluate after Frappe bulk-inserts rows
        const _orig_refresh_field = frm.refresh_field.bind(frm);
        frm.refresh_field = function(fieldname) {
            _orig_refresh_field(fieldname);
            if (fieldname === 'items' && !frm._clearing_items) {
                debounced_set_delivery_number(frm);
            }
        };
    },

    after_save: function(frm) {
        set_delivery_number(frm);
    }
});

frappe.ui.form.on('Sales Invoice Item', {
    items_add:     function(frm) { if (!frm._clearing_items) debounced_set_delivery_number(frm); },
    items_remove:  function(frm) { if (!frm._clearing_items) debounced_set_delivery_number(frm); },
    delivery_note: function(frm) { if (!frm._clearing_items) debounced_set_delivery_number(frm); }
});

function debounced_set_delivery_number(frm) {
    clearTimeout(_dr_debounce_timer);
    _dr_debounce_timer = setTimeout(function() {
        set_delivery_number(frm);
    }, 300);
}

function set_delivery_number(frm) {
    let delivery_notes = [];
    (frm.doc.items || []).forEach(function(row) {
        if (row.delivery_note && !delivery_notes.includes(row.delivery_note)) {
            delivery_notes.push(row.delivery_note);
        }
    });

    if (delivery_notes.length === 0) {
        frm.set_value('custom_delivery_number', '');
        return;
    }

    const request_id = ++_dr_request_id;
    Promise.all(
        delivery_notes.map(dn =>
            frappe.db.get_value('Delivery Note', dn, 'custom_dr_number')
        )
    ).then(function(results) {
        if (request_id !== _dr_request_id) return;
        let dr_numbers = results
            .map(r => r && r.message && r.message.custom_dr_number)
            .filter(Boolean);
        frm.set_value('custom_delivery_number', dr_numbers.join(', '));
    });
}

