function set_rate_precision(frm) {
    const apply_precision = function(customer_precision) {
        const precision = Math.max(cint(customer_precision || 0), 4);
        const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
        if (!grid) return;

        [
            'price_list_rate',
            'base_price_list_rate',
            'rate',
            'base_rate',
            'net_rate',
            'base_net_rate',
            'rate_with_margin',
            'base_rate_with_margin',
            'stock_uom_rate'
        ].forEach(fieldname => {
            grid.update_docfield_property(fieldname, 'precision', precision);
        });

        frm.refresh_field('items');
    };

    if (!frm.doc.customer) {
        apply_precision(4);
        return;
    }

    frappe.db.get_value('Customer', frm.doc.customer, 'custom_decimal_place', function(r) {
        apply_precision(r && r.custom_decimal_place);
    });
}

