frappe.ui.form.on("Sales Order", {
    po_no(frm) {
        // Reset confirmation if PO changes
        frm.__po_confirmed = false;
    },

    validate(frm) {
        if (!frm.doc.po_no || !frm.doc.customer) return;
        if (frm.__po_confirmed) return;

        // Block save while we check duplicates
        frappe.validated = false;

        frappe.call({
            method: "qcmc_logic.utils.check_duplicate_customer_po",
            args: {
                customer: frm.doc.customer,
                po_no: frm.doc.po_no,
                current_name: frm.doc.name
            },
            callback: function(r) {
                const duplicates = r.message || [];

                if (!duplicates.length) {
                    // No duplicates found, proceed with save
                    frm.__po_confirmed = true;
                    frm.save();
                    return;
                }

                const list = duplicates.slice(0, 5).join(', ');
                const msg = __("PO No. {0} was already used for this customer in: {1}. Proceed anyway?", [frm.doc.po_no, list]);

                frappe.confirm(msg,
                    () => {
