qcmc_logic.sales_order_customer_items.show_dialog = function(frm, items) {
    const rows = items.map((item, index) => {
        const rate = qcmc_logic.sales_order_customer_items.parse_rate(item.last_rate || 0);
        const currency = item.currency || frm.doc.currency || "";
        const uom = item.last_uom || "";
        const last_date = item.last_transaction_date ? frappe.datetime.str_to_user(item.last_transaction_date) : "";
        return `
            <tr data-index="${index}" data-selected-rate="${rate}" data-selected-currency="${frappe.utils.escape_html(currency)}" data-selected-uom="${frappe.utils.escape_html(uom)}">
                <td><input type="checkbox" class="history-select"></td>
                <td>${frappe.utils.escape_html(item.item || "")}</td>
                <td>${frappe.utils.escape_html(item.item_name || "")}</td>
                <td><input type="number" class="form-control input-xs history-qty" value="1" min="0" step="any"></td>
                <td class="history-rate-display">${format_currency(rate, currency)}</td>
                <td><button type="button" class="btn btn-xs btn-default history-rate-button">${__("Prices")}</button></td>
                <td class="history-uom-display">${frappe.utils.escape_html(uom)}</td>
                <td>${last_date}</td>
                <td>${cint(item.order_count || 0)}</td>
            </tr>
        `;
    }).join("");

    const d = new frappe.ui.Dialog({
        title: __("Customer Item History"),
        size: "extra-large",
        fields: [
            {
                fieldtype: "HTML",
                fieldname: "items_html",
                options: `
                    <div style="max-height: 60vh; overflow: auto;">
                        <table class="table table-bordered table-sm">
                            <thead>
                                <tr>
                                    <th style="width: 36px;"><input type="checkbox" class="history-select-all"></th>
                                    <th>Item</th>
                                    <th>Item Name</th>
                                    <th style="width: 90px;">Qty</th>
                                    <th>Selected Rate</th>
                                    <th style="width: 90px;">Prices</th>
                                    <th>UOM</th>
                                    <th>Last Bought</th>
                                    <th>Count</th>
                                </tr>
                            </thead>
                            <tbody>${rows}</tbody>
                        </table>
                    </div>
                `
            }
        ],
        primary_action_label: __("Add Selected"),
        primary_action() {
            qcmc_logic.sales_order_customer_items.add_selected_items(frm, d, items);
        }
    });

    d.show();

    d.$wrapper.on("change", ".history-select-all", function() {
        d.$wrapper.find(".history-select").prop("checked", $(this).is(":checked"));
        this.indeterminate = false;
    });

    d.$wrapper.on("change", ".history-select", function() {
        qcmc_logic.sales_order_customer_items.update_select_all_state(d);
    });

    d.$wrapper.on("click", ".history-rate-button", function() {
        const $row = $(this).closest("tr");
        const item = items[cint($row.attr("data-index"))];
        qcmc_logic.sales_order_customer_items.open_rate_dialog(frm, $row, item);
    });

    d.$wrapper.on("keydown", ".history-select, .history-qty", function(e) {
        if (e.key === "F2") {
            e.preventDefault();
            $(this).closest("tr").find(".history-rate-button").trigger("click");
        }
    });
};

qcmc_logic.sales_order_customer_items.update_select_all_state = function(dialog) {
    const $items = dialog.$wrapper.find(".history-select");
    const $checked = $items.filter(":checked");
    const select_all = dialog.$wrapper.find(".history-select-all").get(0);
    if (!select_all) return;

    select_all.checked = $items.length > 0 && $checked.length === $items.length;
    select_all.indeterminate = $checked.length > 0 && $checked.length < $items.length;
};

qcmc_logic.sales_order_customer_items.open_rate_dialog = function(frm, $row, item) {
    if (!item || !item.item) return;

    frappe.call({
        method: "qcmc_logic.customs.sales_order.get_previous_item_rates",
        args: {
            customer: frm.doc.customer,
            item_code: item.item,
            company: frm.doc.company
        },
        freeze: true,
        freeze_message: __("Fetching price history..."),
        callback: function(r) {
            const rates = r.message || [];
            if (!rates.length) {
                frappe.msgprint(__("No price history found for this item."));
                return;
            }

            qcmc_logic.sales_order_customer_items.show_rate_dialog(frm, $row, item, rates);
        }
    });
};

qcmc_logic.sales_order_customer_items.show_rate_dialog = function(frm, $row, item, rates) {
    const current_rate = qcmc_logic.sales_order_customer_items.parse_rate($row.attr("data-selected-rate") || 0);
    const rows = rates.map((rate_row, index) => {
        const currency = rate_row.currency || frm.doc.currency || "";
        const uom = rate_row.uom || item.last_uom || "";
        const rate = qcmc_logic.sales_order_customer_items.parse_rate(rate_row.rate || 0);
        const first_used = rate_row.first_transaction_date ? frappe.datetime.str_to_user(rate_row.first_transaction_date) : "";
        const last_used = rate_row.last_transaction_date ? frappe.datetime.str_to_user(rate_row.last_transaction_date) : "";
        const checked = current_rate === rate || (!current_rate && index === 0) ? "checked" : "";

        return `
            <tr>
                <td><input type="radio" name="history_rate_option" value="${rate}" data-currency="${frappe.utils.escape_html(currency)}" data-uom="${frappe.utils.escape_html(uom)}" ${checked}></td>
                <td>${format_currency(rate, currency)}</td>
                <td>${frappe.utils.escape_html(uom)}</td>
                <td>${first_used}</td>
                <td>${last_used}</td>
                <td>${cint(rate_row.times_used || 0)}</td>
            </tr>
        `;
    }).join("");

    const d = new frappe.ui.Dialog({
        title: __("Price History: {0}", [item.item]),
        size: "large",
        fields: [
            {
                fieldtype: "HTML",
                fieldname: "rates_html",
                options: `
                    <table class="table table-bordered table-sm">
                        <thead>
                            <tr>
                                <th style="width: 36px;"></th>
                                <th>Rate</th>
                                <th>UOM</th>
                                <th>First Used</th>
                                <th>Last Used</th>
                                <th>Times Used</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                `
            }
        ],
        primary_action_label: __("Use Price"),
        primary_action() {
            const $selected = d.$wrapper.find('input[name="history_rate_option"]:checked');
            const selected_rate = qcmc_logic.sales_order_customer_items.parse_rate($selected.val());
            const currency = $selected.data("currency") || frm.doc.currency || "";
            const uom = $selected.data("uom") || item.last_uom || "";

            $row.attr("data-selected-rate", selected_rate);
            $row.attr("data-selected-currency", currency);
            $row.attr("data-selected-uom", uom);
            $row.find(".history-rate-display").text(format_currency(selected_rate, currency));
            $row.find(".history-uom-display").text(uom);
            d.hide();
        }
    });

    d.show();
};

qcmc_logic.sales_order_customer_items.apply_selected_rate = function(frm, child, selected_rate) {
    const values = {
        price_list_rate: selected_rate,
        rate: selected_rate,
        discount_percentage: 0,
        discount_amount: 0
    };

    return frappe.model.set_value(child.doctype, child.name, values).then(function() {
        return frm.script_manager.trigger("rate", child.doctype, child.name);
    });
};

qcmc_logic.sales_order_customer_items.add_selected_items = async function(frm, dialog, items) {
    let added = 0;
    const rows = dialog.$wrapper.find("tbody tr").toArray();

    for (const row of rows) {
        const $row = $(row);
        if (!$row.find(".history-select").is(":checked")) continue;

        const item = items[cint($row.attr("data-index"))];
        const qty = flt($row.find(".history-qty").val());
        if (!item || qty <= 0) continue;

        const selected_rate = qcmc_logic.sales_order_customer_items.parse_rate($row.attr("data-selected-rate") || item.last_rate || 0);
        const selected_uom = $row.attr("data-selected-uom") || item.last_uom || "";
        const child = frm.add_child("items");
        child.item_code = item.item;
        child.item_name = item.item_name;
        child.qty = qty;
        child.uom = selected_uom;
        child.rate = selected_rate;
        child.price_list_rate = selected_rate;
        child.discount_percentage = 0;
        child.discount_amount = 0;
        child.__customer_history_rate = selected_rate;

        await frm.script_manager.trigger("item_code", child.doctype, child.name);
        await qcmc_logic.sales_order_customer_items.apply_selected_rate(frm, child, selected_rate);
        added += 1;
    }

    if (!added) {
        frappe.msgprint(__("Please select at least one item with a quantity greater than zero."));
        return;
    }

    frm.refresh_field("items");
    dialog.hide();
};

