// Work Order: Custom Print Format based on Workstation
// Priority:
// 1. Operation with "Is Final Finished Good" checked
// 2. Last operation with workstation
// 3. BOM Operation fallback

frappe.ui.form.on('Work Order', {
    refresh: function(frm) {
        frm.print_doc = function() {
            handle_custom_print(frm);
        };

        if (frm.toolbar && frm.toolbar.print_me) {
            frm.toolbar.print_me = function() {
                handle_custom_print(frm);
            };
        }

        frm.add_custom_button(__('Print'), function() {
            handle_custom_print(frm);
        }).removeClass('btn-default').addClass('btn-primary');
    }
});

async function handle_custom_print(frm) {
    try {
        let workstation = null;

        // 1. Get workstation from Work Order Operations
        if (frm.doc.operations && frm.doc.operations.length > 0) {
            console.table(frm.doc.operations.map(op => ({
                idx: op.idx,
                operation: op.operation,
                workstation: op.workstation,
                is_final_finished_good: op.is_final_finished_good
            })));

            // Prefer row checked as Final Finished Good
            let final_op = frm.doc.operations.find(op =>
                op.workstation && cint(op.is_final_finished_good) === 1
            );

            // Fallback to last operation with workstation
            let last_op = [...frm.doc.operations]
                .reverse()
                .find(op => op.workstation);

            workstation = final_op?.workstation || last_op?.workstation || null;
        }

        // 2. Fallback: get workstation from BOM Operation
        if (!workstation && frm.doc.bom_no) {
            const bom_res = await frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'BOM Operation',
                    filters: [
                        ['parent', '=', frm.doc.bom_no],
                        ['parenttype', '=', 'BOM']
                    ],
                    fields: [
                        'workstation',
                        'idx',
                        'is_final_finished_good'
                    ],
                    order_by: 'idx desc',
                    limit_page_length: 20
                }
            });

            if (bom_res.message && bom_res.message.length > 0) {
                let final_bom_op = bom_res.message.find(op =>
                    op.workstation && cint(op.is_final_finished_good) === 1
                );

                let last_bom_op = bom_res.message.find(op => op.workstation);

                workstation = final_bom_op?.workstation || last_bom_op?.workstation || null;
            }
        }

        let print_format = null;

        // 3. Get custom print format from Workstation
        if (workstation) {
            const ws_res = await frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Workstation',
                    filters: {
                        name: workstation
                    },
                    fieldname: 'custom_print_format'
                }
            });

            if (ws_res.message && ws_res.message.custom_print_format) {
                print_format = ws_res.message.custom_print_format;
            }
        }

        console.log('[WO Print]', {
            workstation: workstation,
            print_format: print_format
        });

        if (!print_format) {
            frappe.msgprint(__('No custom print format found for workstation: ') + (workstation || 'None'));
        }

        let url = '/printview?' + $.param({
            doctype: frm.doc.doctype,
            name: frm.doc.name,
            format: print_format || '',
            no_letterhead: 0
        });

        let w = window.open(url);

        if (!w) {
            frappe.msgprint(__('Please allow pop-ups to continue.'));
        }

    } catch (err) {
        console.error('[WO Print] Error:', err);

        window.open('/printview?' + $.param({
            doctype: frm.doc.doctype,
            name: frm.doc.name
        }));
    }
}

frappe.listview_settings["ZKTeco Device"] = {
    onload(listview) {
        // Add a primary button on the toolbar
        listview.page.add_inner_button(__("Fetch Attendance Logs"), function() {
            frappe.confirm(
                __("This will fetch logs from all active ZKTeco devices. Continue?"),
                () => {
                    frappe.call({
                        method: "zkteco_integration.zkteco_integration.zk_downloader.fetch_and_insert_attendance_logs",
                        freeze: true,
                        freeze_message: __("Fetching biometric data..."),
                        callback: function(r) {
                            if (r.message && r.message.success) {
                                const s = r.message;
                                let msg = `
                                    ✅ Devices processed: <b>${s.devices_processed}</b><br>
                                    👥 Total logs read: <b>${s.total_logs}</b><br>
                                    📥 Inserted: <b>${s.inserted_logs}</b><br>
                                    🔁 Duplicates skipped: <b>${s.skipped_duplicates}</b><br>
                                    ⚠️ Missing employees: <b>${s.missing_employees}</b>
                                `;
                                if (s.errors && s.errors.length) {
                                    msg += `<br><br>❌ Errors:<br>${s.errors.join("<br>")}`;
                                }
                                frappe.msgprint({
                                    title: __("Biometric Sync Summary"),
                                    indicator: "green",
                                    message: msg
                                });
                                listview.refresh();
                            } else {
                                frappe.msgprint({
                                    title: __("Failed"),
                                    indicator: "red",
                                    message: (r.message && r.message.message) || "Error fetching logs."
                                });
                            }
                        }
                    });
                }
            );
        }, __("Actions")); // Group under "Actions" section (optional)
    }
};

frappe.ui.form.on("ZKTeco Device", {
    refresh(frm) {

        // ── Test Connection ──────────────────────────────────────────
        frm.add_custom_button(__("Test Connection"), function () {
            if (!frm.doc.device_ip) {
                frappe.msgprint({ title: __("Missing IP"), message: __("Please enter an IP Address first."), indicator: "orange" });
                return;
            }
            frappe.call({
                method: "qcmc_logic.api.zkteco.test_connection",
                args: { device_name: frm.doc.name },
                freeze: true,
                freeze_message: __("Testing connection..."),
                callback(r) {
                    const res = r.message;
                    if (res && res.success) {
                        let msg = `<b>Connected to ${frm.doc.device_ip}:${frm.doc.port}</b>`;
                        if (res.firmware && res.firmware !== "N/A") msg += `<br>Firmware: ${res.firmware}`;
                        if (res.serial && res.serial !== "N/A") msg += `<br>Serial: ${res.serial}`;
                        frappe.msgprint({ title: __("Connection Successful"), message: msg, indicator: "green" });
                    } else {
                        frappe.msgprint({ title: __("Connection Failed"), message: (res && res.message) || "Unknown error.", indicator: "red" });
                    }
                }
            });
        }, __("Actions"));

        // ── Fetch Attendance ─────────────────────────────────────────
        frm.add_custom_button(__("Fetch Attendance"), function () {

            let d = new frappe.ui.Dialog({
                title: __("Fetch Attendance Logs"),
                fields: [
                    {
                        fieldname: "from_date",
                        fieldtype: "Date",
                        label: __("From Date"),
                        reqd: 1,
                        default: frappe.datetime.add_months(frappe.datetime.get_today(), -1)
                    },
                    {
                        fieldname: "to_date",
                        fieldtype: "Date",
                        label: __("To Date"),
                        reqd: 1,
                        default: frappe.datetime.get_today()
                    },
                    { fieldname: "sb", fieldtype: "Section Break" },
                    {
                        fieldname: "select_device",
                        fieldtype: "Check",
                        label: __("Select Specific Device"),
                        default: 0
                    },
                    {
                        fieldname: "device",
                        fieldtype: "Link",
                        label: __("Device"),
                        options: "ZKTeco Device",
                        depends_on: "eval:doc.select_device == 1",
                        mandatory_depends_on: "eval:doc.select_device == 1"
                    }
                ],
                primary_action_label: __("Download Logs"),
                primary_action(values) {
                    let device_name = values.select_device ? values.device : frm.doc.name;

                    frappe.call({
                        method: "qcmc_logic.api.zkteco.fetch_attendance_for_device",
                        args: {
                            device_name: device_name,
                            start_date: values.from_date,
                            end_date: values.to_date
                        },
                        freeze: true,
                        freeze_message: __("Fetching attendance logs..."),
                        callback(r) {
                            d.hide();
                            const s = r.message;
                            if (s && s.success) {
                                frappe.msgprint({
                                    title: __("Download Complete"),
                                    indicator: "green",
                                    message: `
                                        Total logs read: <b>${s.total_logs}</b><br>
                                        Inserted: <b>${s.inserted_logs}</b><br>
                                        Duplicates skipped: <b>${s.skipped_duplicates}</b><br>
                                        Missing employees: <b>${s.missing_employees}</b>
                                        ${s.errors && s.errors.length ? "<br><br>Errors:<br>" + s.errors.join("<br>") : ""}
                                    `
                                });
                                frm.reload_doc();
                            } else {
                                frappe.msgprint({ title: __("Failed"), message: (s && s.errors && s.errors[0]) || "Error fetching logs.", indicator: "red" });
                            }
                        }
                    });
                },
                secondary_action_label: __("Download All Devices"),
                secondary_action() {
                    let values = d.get_values();
                    if (!values || !values.from_date || !values.to_date) {
                        frappe.msgprint({ title: __("Missing Dates"), message: __("Please fill From Date and To Date."), indicator: "orange" });
                        return;
                    }
                    frappe.call({
                        method: "qcmc_logic.api.zkteco.fetch_and_insert_attendance_logs",
                        args: {
                            start_date: values.from_date,
                            end_date: values.to_date
                        },
                        freeze: true,
                        freeze_message: __("Fetching from all devices..."),
                        callback(r) {
                            d.hide();
                            const s = r.message;
                            if (s && s.success) {
                                frappe.msgprint({
                                    title: __("Download Complete — All Devices"),
                                    indicator: "green",
                                    message: `
                                        Devices processed: <b>${s.devices_processed}</b><br>
                                        Total logs read: <b>${s.total_logs}</b><br>
                                        Inserted: <b>${s.inserted_logs}</b><br>
                                        Duplicates skipped: <b>${s.skipped_duplicates}</b><br>
                                        Missing employees: <b>${s.missing_employees}</b>
                                        ${s.errors && s.errors.length ? "<br><br>Errors:<br>" + s.errors.join("<br>") : ""}
                                    `
                                });
                                frm.reload_doc();
                            } else {
                                frappe.msgprint({ title: __("Failed"), message: (s && s.message) || "Error fetching logs.", indicator: "red" });
                            }
                        }
                    });
                }
            });

            d.show();

        }, __("Actions"));
    }
});

